// PayPal Server SDK (@paypal/paypal-server-sdk), generated by APIMatic from PayPal's API spec.
// Used for Orders and Payments: typed requests, built-in OAuth, retries, and idempotency keys.
// Disputes, Invoicing and Tracking batch are not in this SDK, so lib/paypal.js calls those via REST.
import { Client, Environment, LogLevel, OrdersController, PaymentsController, CheckoutPaymentIntent } from '@paypal/paypal-server-sdk';

const ID = process.env.PAYPAL_CLIENT_ID;
const SECRET = process.env.PAYPAL_CLIENT_SECRET;
const LIVE = !(process.env.PAYPAL_BASE || 'sandbox').includes('sandbox');

let orders = null;
let payments = null;
if (ID && SECRET) {
  const client = new Client({
    clientCredentialsAuthCredentials: { oAuthClientId: ID, oAuthClientSecret: SECRET },
    environment: LIVE ? Environment.Production : Environment.Sandbox,
    timeout: 20000,
    logging: { logLevel: LogLevel.Error, logRequest: { logBody: false }, logResponse: { logHeaders: false } },
  });
  orders = new OrdersController(client);
  payments = new PaymentsController(client);
}

const sdkError = (e) => {
  const body = e?.result ?? e?.body;
  return new Error(`PayPal SDK ${e?.statusCode ?? ''}: ${typeof body === 'string' ? body.slice(0, 300) : JSON.stringify(body ?? e?.message).slice(0, 300)}`);
};
const run = async (fn) => { try { return (await fn()).result; } catch (e) { throw sdkError(e); } };

export const sdk = {
  available: () => !!orders,

  createOrder: ({ name, price, requestId }) => run(() => orders.createOrder({
    paypalRequestId: requestId,
    body: {
      intent: CheckoutPaymentIntent.Capture,
      purchaseUnits: [{ description: name, amount: { currencyCode: 'USD', value: price.toFixed(2) } }],
    },
    prefer: 'return=minimal',
  })),

  // Idempotent: the same order ID always uses the same request ID, so a retried capture
  // can never charge the buyer twice.
  captureOrder: (id) => run(() => orders.captureOrder({ id, paypalRequestId: `capture-${id}`, prefer: 'return=representation' })),

  getOrder: (id) => run(() => orders.getOrder({ id })),

  getCapture: (captureId) => run(() => payments.getCapturedPayment({ captureId })),

  trackOrder: ({ orderId, captureId, trackingNumber, carrier }) => run(() => orders.createOrderTracking({
    id: orderId,
    body: { captureId, trackingNumber, carrier, notifyPayer: true },
  })),
};
